from pathlib import Path
import xml.etree.ElementTree as ET

CAT=Path('Legiones Astartes.cat')
GST=Path('Prohammer 30k.gst')
IDX=Path('index.xml')
OUT=Path('inspection-r72-night-lords-final.txt')
CNS='http://www.battlescribe.net/schema/catalogueSchema'
GNS='http://www.battlescribe.net/schema/gameSystemSchema'
INS='http://www.battlescribe.net/schema/dataIndexSchema'
ET.register_namespace('',CNS); ET.register_namespace('',GNS); ET.register_namespace('',INS)
C=lambda t:f'{{{CNS}}}{t}'; G=lambda t:f'{{{GNS}}}{t}'; I=lambda t:f'{{{INS}}}{t}'
ct=ET.parse(CAT); cr=ct.getroot(); gt=ET.parse(GST); gr=gt.getroot(); it=ET.parse(IDX); ir=it.getroot()
if cr.get('revision')!='71' or gr.get('revision')!='39':
    raise RuntimeError(f'Expected CAT71/GST39 baseline, got CAT{cr.get("revision")}/GST{gr.get("revision")}')

def ensure(p,t,ns=CNS):
    Q=C if ns==CNS else (G if ns==GNS else I)
    x=p.find(Q(t))
    if x is None:x=ET.SubElement(p,Q(t))
    return x

def byid(root,i):return next((e for e in root.iter() if e.get('id')==i),None)
def links(g):return g.findall('./'+C('entryLinks')+'/'+C('entryLink'))
def has_target(g,target):return any(x.get('targetId')==target for x in links(g))
def constraint(p,i,typ,val,field='selections',scope='parent'):
    return ET.SubElement(ensure(p,'constraints'),C('constraint'),{'id':i,'type':typ,'value':str(val),'field':field,'scope':scope,'shared':'true','includeChildSelections':'false','includeChildForces':'false'})
def link(g,i,n,target):
    x=ET.SubElement(ensure(g,'entryLinks'),C('entryLink'),{'id':i,'name':n,'type':'selectionEntry','targetId':target,'hidden':'false','import':'true'})
    constraint(x,i+'-max','max',1)
    return x

def parent_map(root):return {c:p for p in root.iter() for c in p}
PM=parent_map(cr)
def ancestor_unit(e):
    p=e
    while p is not None:
        if p.tag==C('selectionEntry') and p.get('type')=='unit':return p
        p=PM.get(p)
    return None

def group_depth(g,u):
    d=0;p=g
    while p is not None and p is not u:
        p=PM.get(p);d+=1
    return d

def sergeant_armoury_groups(u):
    return [g for g in u.iter(C('selectionEntryGroup')) if 'sergeant armoury' in (g.get('name') or '').lower()]
def choose_outer(groups,u):
    return min(groups,key=lambda g:group_depth(g,u)) if groups else None
def descendant_named(u,phrase):
    return [g for g in u.iter(C('selectionEntryGroup')) if phrase in (g.get('name') or '').lower()]

def remove_target_from_group(g,target):
    q=g.find(C('entryLinks'))
    if q is None:return 0
    removed=0
    for x in list(q):
        if x.get('targetId')==target:q.remove(x);removed+=1
    return removed

# 1) Project armoury standard: Headsmen and Headtakers have 50-point Armoury access,
# but Artificer Armour is NOT a universal Sergeant-compatible item. Remove the accidental link
# from every canonical/copy Armoury block generated by Revision 71.
removed_art=0
for g in cr.iter(C('selectionEntryGroup')):
    n=(g.get('name') or '').lower()
    if 'headsman armoury' in n or 'headtaker armoury' in n:
        for sub in g.iter(C('selectionEntryGroup')):
            removed_art+=remove_target_from_group(sub,'gear-hq-artificer')
        removed_art+=remove_target_from_group(g,'gear-hq-artificer')

# 2) Complete Sergeant Night Lords Armoury coverage.
# Trophies: every squad Sergeant. Chainglaive: any Sergeant with actual Space Marine Armoury access.
# We use the unit's existing Sergeant Armoury container, preserving its 50-point cap.
GENERIC_PREFIXES=(
 'legion tactical squad','legion assault squad','legion breacher siege squad','legion reconnaissance squad',
 'legion veteran squad','legion destroyer squad','legion seeker squad','legion heavy support squad',
 'legion command squad','legion honour guard squad'
)
sg_units=0; added_trophies=0; added_chain=0
seen_units=set()
for u in cr.iter(C('selectionEntry')):
    if u.get('type')!='unit':continue
    name=(u.get('name') or '').lower()
    if not any(name.startswith(x) for x in GENERIC_PREFIXES):continue
    if id(u) in seen_units:continue
    seen_units.add(id(u))
    ag=sergeant_armoury_groups(u)
    if not ag:continue
    sg_units+=1
    outer=choose_outer(ag,u)
    # Prefer dedicated nested groups where the catalogue has them.
    two=next((g for g in descendant_named(u,'two-handed weapons') if group_depth(g,u)>group_depth(outer,u)),None)
    war=next((g for g in u.iter(C('selectionEntryGroup')) if 'wargear' in (g.get('name') or '').lower() and group_depth(g,u)>group_depth(outer,u)),None)
    trophy_dest=war or outer
    chain_dest=two or outer
    # Avoid duplicate exposure anywhere in the same unit.
    if not any(x.get('targetId')=='r44-nl-trophies' for x in u.iter(C('entryLink'))):
        link(trophy_dest,f'r72-nl-sgt-trophy-{sg_units}','Trophies of Judgement','r44-nl-trophies');added_trophies+=1
    if not any(x.get('targetId')=='r44-nl-chainglaive' for x in u.iter(C('entryLink'))):
        link(chain_dest,f'r72-nl-sgt-chain-{sg_units}','Nostraman Chainglaive','r44-nl-chainglaive');added_chain+=1

# 3) Horror Cult: squads which already possess Trophies still pay the Rite's +25 upgrade to gain
# the full Beyond Judgement effect. Rename the local selector so New Recruit does not look like it
# is selling the same physical Trophies twice.
pre_trophied=('terror squad','night raptor squad','atramentar flay-clade')
renamed_bj=0
for u in cr.iter(C('selectionEntry')):
    if u.get('type')!='unit':continue
    if not any(x in (u.get('name') or '').lower() for x in pre_trophied):continue
    for e in u.iter(C('selectionEntry')):
        if (e.get('name') or '').startswith('Beyond Judgement — Trophies of Judgement & Fear'):
            e.set('name','Beyond Judgement — Fear (Trophies already equipped)')
            for r in e.iter(C('rule')):
                if (r.get('name') or '')=='Beyond Judgement':
                    d=r.find(C('description'))
                    if d is not None:d.text='This squad already carries Trophies of Judgement. Under Horror Cult it may still purchase Beyond Judgement for +25 points per unit; doing so grants Fear and treats the squad as equipped with Trophies of Judgement in the manner specified by the Rite. Measure the 8-inch Leadership penalty from any model. Trophies penalties remain non-cumulative.'
            renamed_bj+=1

# Source-accuracy checks for Curze / Terror Squad decisions.
cur=byid(cr,'r41-unit-viii-9-viii-konrad-curze-the-night-haunter')
terror=byid(cr,'r41-unit-viii-0-terror-squad')
assert cur is not None and terror is not None
assert any('Legion Terminator Command Squad'==(x.get('name') or '') for x in cur.iter(C('selectionEntry')))
assert any('Atramentar Flay-Clade'==(x.get('name') or '') for x in cur.iter(C('selectionEntry')))
assert any('Night Raptor Squad'==(x.get('name') or '') for x in cur.iter(C('selectionEntry')))
assert any('Terror Squad'==(x.get('name') or '') for x in cur.iter(C('selectionEntry')))
# Current Terror Squad entry does not grant Kraken Light Bolts, so it must not receive that selector.
assert not any(x.get('targetId')=='r44-nl-kraken-bolts' for x in terror.iter(C('entryLink')))

# Validate the two custom leader Armouries no longer expose Artificer Armour.
for g in cr.iter(C('selectionEntryGroup')):
    n=(g.get('name') or '').lower()
    if 'headsman armoury' in n or 'headtaker armoury' in n:
        assert not any(x.get('targetId')=='gear-hq-artificer' for x in g.iter(C('entryLink'))),g.get('name')

# Every generic unit with a Sergeant Armoury must now expose both legal Night Lords items somewhere
# in that unit; shared-item gating keeps them hidden for other Legions.
missing=[]
for u in cr.iter(C('selectionEntry')):
    if u.get('type')!='unit':continue
    name=(u.get('name') or '').lower()
    if not any(name.startswith(x) for x in GENERIC_PREFIXES):continue
    if not sergeant_armoury_groups(u):continue
    tg=any(x.get('targetId')=='r44-nl-trophies' for x in u.iter(C('entryLink')))
    ch=any(x.get('targetId')=='r44-nl-chainglaive' for x in u.iter(C('entryLink')))
    if not (tg and ch):missing.append((u.get('id'),u.get('name'),tg,ch))
if missing:raise RuntimeError('Incomplete Night Lords Sergeant Armoury coverage: '+repr(missing[:20]))

# Duplicate-ID validation.
def dupids(root):
    seen=set();dups=[]
    for x in root.iter():
        i=x.get('id')
        if not i:continue
        if i in seen:dups.append(i)
        seen.add(i)
    return dups
for root,label in ((cr,'CAT'),(gr,'GST')):
    d=dupids(root)
    if d:raise RuntimeError(f'Duplicate {label} IDs: {d[:20]}')

# Final cache/version bump after structural polish.
cr.set('revision','72');cr.set('gameSystemRevision','40');gr.set('revision','40')
for e in ir.iter(I('dataIndexEntry')):
    if e.get('filePath')=='Legiones Astartes.cat':e.set('dataRevision','72')
    if e.get('filePath')=='Prohammer 30k.gst':e.set('dataRevision','40')

ET.indent(ct,space='  ');ET.indent(gt,space='  ');ET.indent(it,space='  ')
ET.register_namespace('',CNS);ct.write(CAT,encoding='utf-8',xml_declaration=True)
ET.register_namespace('',GNS);gt.write(GST,encoding='utf-8',xml_declaration=True)
ET.register_namespace('',INS);it.write(IDX,encoding='utf-8',xml_declaration=True)
ET.parse(CAT);ET.parse(GST);ET.parse(IDX)

OUT.write_text(f'''Revision 72 — Night Lords final standards polish\nCatalogue revision: 72\nGame-system revision: 40\n\nFinal fixes applied:\n- Removed accidental universal Artificer Armour access from Headsman/Headtaker 50-point Sergeant Armouries ({removed_art} links removed across canonical/copy entries).\n- Completed Night Lords Sergeant Armoury coverage across {sg_units} generic/copy units: {added_trophies} missing Trophies links and {added_chain} missing Chainglaive links added through existing Sergeant Armoury containers.\n- Horror Cult Beyond Judgement selectors on already-Trophied Terror/Raptor/Atramentar units were relabelled to avoid presenting duplicate physical Trophies while retaining the source-required +25 Rite upgrade and Fear effect ({renamed_bj} selectors).\n- Current Curze retinue structure was revalidated: Terminator Command, Atramentar, Night Raptors, Terror Squad.\n- Current Terror Squad source was revalidated: no Kraken Light Bolts option is granted by its unit entry.\n- Duplicate IDs and XML parse validation passed.\n- CAT/GST/index revisions bumped for New Recruit cache refresh.\n''',encoding='utf-8')
print(OUT.read_text())
